// ================== CONFIGURAÇÃO (edite aqui) ==================
const CONFIG = {
  // Endereços internos dos serviços (rede Docker do seu painel).
  // Easypanel: http://<projeto>_<serviço>:<porta> | Dokploy: nome interno da aplicação
  bridgeUrl: 'http://SEUPROJETO_claude-bridge:3000',
  bridgeToken: 'TROQUE-PELO-BRIDGE_TOKEN',
  evolutionUrl: 'http://SEUPROJETO_evolution-api:8080',
  evolutionApiKey: 'TROQUE-PELA-APIKEY-DO-EVOLUTION',
  instancia: 'NOME-DA-INSTANCIA',

  // true  = o número conectado no Evolution é o SEU (você fala num grupo só seu;
  //         suas mensagens chegam como fromMe)
  // false = o Evolution usa um número separado (o "bot"); você manda do seu número
  numeroProprio: true,

  // Toda resposta do Claude começa com isto. Mensagens que começam com isto são
  // ignoradas, para o Claude não responder a si mesmo.
  prefixoBot: '🤖 ',

  // JID do grupo -> pasta do grupo no claude-bridge
  grupos: {
    // '120363000000000001@g.us': 'meu-claude',
    // '120363000000000002@g.us': 'minha-api',
    // '120363000000000003@g.us': 'viagem',
  },

  // Só vale quando numeroProprio = false. Vazio = qualquer pessoa do grupo.
  remetentesPermitidos: [
    // '5531999999999@s.whatsapp.net',
  ],
};
// ===============================================================

const body = $json.body || $json;
if (body.event !== 'messages.upsert' || !body.data || !body.data.key) return [];

const d = body.data;
const key = d.key;
const jid = key.remoteJid || '';
const pasta = CONFIG.grupos[jid];
if (!pasta) return []; // grupo não cadastrado: ignora

const m = d.message || {};
const texto = (
  m.conversation ||
  (m.extendedTextMessage && m.extendedTextMessage.text) ||
  (m.imageMessage && m.imageMessage.caption) ||
  (m.documentMessage && m.documentMessage.caption) ||
  ''
).trim();

// Evita laço: nunca reage às próprias respostas
if (texto.startsWith(CONFIG.prefixoBot.trim())) return [];

if (CONFIG.numeroProprio) {
  if (!key.fromMe) return []; // no modo número próprio, só você fala
} else {
  if (key.fromMe) return [];
  const remetente = key.participant || d.participant || '';
  if (CONFIG.remetentesPermitidos.length && !CONFIG.remetentesPermitidos.includes(remetente)) return [];
}

const payload = { grupo: pasta, texto, remetente: d.pushName || '' };

const tipo = d.messageType || Object.keys(m)[0] || '';
if (tipo === 'imageMessage' || tipo === 'documentMessage') {
  const midia = m[tipo] || {};
  if (m.base64) {
    payload.arquivo = {
      base64: m.base64,
      mimetype: midia.mimetype || '',
      nome: midia.fileName || (tipo === 'imageMessage' ? 'foto' : 'documento'),
    };
  } else {
    payload.texto += '\n[Chegou um arquivo, mas o Evolution não mandou o conteúdo. Avise que é preciso ligar "Webhook Base64" na instância.]';
  }
} else if (tipo === 'audioMessage') {
  payload.texto = '[O usuário mandou um áudio. A transcrição ainda não está ativada: avise isso numa frase e peça para mandar por texto.]';
}

if (!payload.texto.trim() && !payload.arquivo) return [];

return [{
  json: {
    jid,
    payload,
    bridgeUrl: CONFIG.bridgeUrl,
    bridgeToken: CONFIG.bridgeToken,
    evolutionUrl: CONFIG.evolutionUrl,
    evolutionApiKey: CONFIG.evolutionApiKey,
    instancia: CONFIG.instancia,
    prefixoBot: CONFIG.prefixoBot,
  },
}];
